function openModal(html,view=''){if(view!=='fishing'){fishingHolding=false;if(state.outdoors)state.outdoors.fishing=null;}if(modalView==='feedback'&&view!=='feedback')dismissFeedback();controls?.stop();harvestClock=0;for(const cell of cells)cell.pickProgress=0;modalView=view;$('modalBody').innerHTML=html;if(!modal.open)modal.showModal();}
function walkTo(target){closeModal();if(controls)controls.target={x:target.x,z:target.z};}
