 modal.querySelectorAll('[data-hive-visit]').forEach(b=>b.onclick=()=>walkTo(HIVES[Number(b.dataset.hiveVisit)]));$('storeHoney').onclick=()=>{storeHoney(state);save();updateApiaryCounts();};$('apiaryBack').onclick=openGardenMenu;$('apiaryFarm').onclick=()=>state.village.farm.built?openFoodKitchen():toast('Baue ab Level 18 die Schneckenfarm.');
