function openSettings(){openModal(title('MACHT ES EUCH GEMÜTLICH','Euer Garten, euer Tempo.','Finger auf eine freie Stelle setzen und ziehen: Dort erscheint dein Joystick. Auch WASD und Pfeiltasten bewegen dich. Leertaste führt zum Verkauf. Auf ↑-Flächen stehen bleiben, um zu bauen und aufzurüsten.')+`<div class="settings-row"><button class="modal-action secondary" id="toggleSound">Klang ${state.sound?'aus':'an'}</button><button class="modal-action secondary" id="toggleMotion">${state.reducedMotion?'Mehr':'Weniger'} Bewegung</button></div><button class="modal-action secondary" id="editNames">Eure Namen ändern</button><button class="modal-action secondary" id="journal">Erinnerungsbuch · ${state.achievements.length} / ${ACHIEVEMENTS.length}</button><button class="modal-action secondary" id="roundSettings">${embedded?'Gartenrunden':'Gartenrunden & Vorschau'}</button><button class="modal-action secondary" id="settingsStock">Lager und Werkstätten</button><div class="settings-row"><button class="modal-action secondary" id="exportSave">Spielstand sichern ↓</button><button class="modal-action secondary" id="importSave">Sicherung laden ↑</button></div><input class="file-input" id="saveFile" type="file" accept=".json,application/json"><p class="shop-note">Automatisch alle 10 Sekunden auf diesem Gerät gespeichert. Nach 10 aktiven Minuten schläfst du ein; Menüs und Pausen zählen nicht mit. Warnungen erscheinen zwei Minuten und eine Minute vorher. Ab Minute fünf wachsen Pflanzen langsamer, ab Minute neun nicht mehr nach. Reife Pflanzen bleiben bis zum Einschlafen erntbar. In Pausen verarbeiten Werkstätten nur eine kleine Menge vorhandener Zutaten. Es wird dabei nichts geerntet oder verkauft. Im Garten kannst du auch nach dem Tagesabschluss weiter sammeln; Pflanzen wachsen allmählich langsamer nach.</p><button class="modal-action secondary" id="help">Wie funktioniert der Garten?</button><button class="modal-action danger" id="resetGame">Ganz von vorne anfangen</button>`,'settings');
  $('toggleSound').onclick=()=>{state.sound=!state.sound;sound('build');save();syncUI();openSettings();};$('toggleMotion').onclick=()=>{state.reducedMotion=!state.reducedMotion;document.body.classList.toggle('reduced-motion',state.reducedMotion);save();openSettings();};$('editNames').onclick=openNames;$('journal').onclick=openJournal;$('settingsStock').onclick=openInventory;$('roundSettings').onclick=openRounds;
  $('exportSave').onclick=()=>{save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='mondgarten-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Eure Gartengeschichte wurde gesichert.');};
  $('importSave').onclick=()=>$('saveFile').click();$('saveFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw new Error('Die Datei ist zu groß.');const imported=normalize(JSON.parse(await file.text()));openModal(title('EINE GESPEICHERTE GESCHICHTE','Diesen Garten laden?',`${esc(imported.names.join(' & '))} · Ausbaustufe ${gardenLevel(imported)} · ${format(imported.coins)} ✧`)+`<p>Der aktuelle Spielstand auf diesem Gerät wird durch diese Sicherung ersetzt.</p><button class="modal-action" id="confirmImport">Sicherung übernehmen</button><button class="modal-action secondary" id="cancelImport">Abbrechen</button>`,'import');$('cancelImport').onclick=openSettings;$('confirmImport').onclick=()=>{state=imported;offlineEarnings(state);resetWorld();tutorial(state.tutorial);document.body.classList.toggle('reduced-motion',state.reducedMotion);save();closeModal();toast('Euer Garten ist wieder da.');};}catch(e){toast('Diese Sicherung konnte nicht geladen werden. '+e.message);}};
  $('help').onclick=()=>{openModal(title('ALLES WÄCHST ZUSAMMEN','Vom kleinen Beet zum Gartenparadies.','Ernte Blumen und verkaufe sie zunächst als Rohstoffe. Kaufe auf den markierten Bodenflächen eine bessere Sichel, mehr Platz und weitere Beete.')+`<p>Baue die Blumenbinderei, bringe Mondblüten links an ihren Tisch, hole rechts fertige Sträuße ab und verkaufe sie am Stand. Die Sternenteeküche verarbeitet Lavendel, die Destille Korallenblüten. Die Mondalchemie braucht später Sternentee, Duftöl und Glühpilze.</p><p>Schnecken ernten selbst und bringen ihre Bündel direkt zur passenden Werkstatt. Fehlt diese, verkaufen sie am Stand. Ist die Werkstatt voll, verkaufen sie den Rest am Stand. Im Schneckenmenü kannst du auch Lagerlieferungen zuweisen. Nachts ziehen sich die Schnecken in ihre Häuschen zurück. Baue Fundament, Wände und Dach von Schneckis Zuhause. Beim Einzug übernimmt Schnecki die Transporte und den Verkauf. So wird der Garten nach und nach selbstständig.</p><p>Du und deine Ernteschnecken ernten mit 25 % Zusatzwert. Die Blumenbinderei verdoppelt den Wert ihrer verwendeten Blumen bei 15 Sekunden Grundzeit. Bessere Beete erhöhen den Ertrag, Gartenpflege beschleunigt das Nachwachsen und bessere Werkstätten produzieren schneller und wertvoller.</p><p>Auf Kauf-Flächen wird der Preis nach kurzem Stillstehen nach und nach bezahlt. Anzahlungen bleiben erhalten. Verlasse die Fläche nach einem Kauf kurz, bevor du eine weitere Stufe kaufst.</p><button class="modal-action" id="backToGarden">Zurück in meinen Garten</button>`,'help');$('backToGarden').onclick=closeModal;};
  $('resetGame').onclick=()=>{openModal(title('EIN GANZ NEUES BLATT','Wirklich neu anfangen?','Beete, Werkstätten, Schnecken, Vorräte und Verbesserungen auf diesem Gerät werden gelöscht. Sichere deinen Spielstand vorher, wenn du ihn behalten möchtest.')+'<button class="modal-action danger" id="confirmReset">Ja, diesen Spielstand löschen</button><button class="modal-action secondary" id="cancelReset">Meinen Garten behalten</button>','reset');$('cancelReset').onclick=openSettings;$('confirmReset').onclick=()=>{state=embedded?prepareHostedState(freshState()):freshState();if(embedded)syncCompanionActions(state,JSON.parse(localStorage.getItem(COMPANION.journalKey)||'null'));clock=0;document.body.classList.remove('reduced-motion');resetWorld();tutorial(0);save();closeModal();};};
}
$('settings').onclick=openSettings;$('sound').onclick=()=>{state.sound=!state.sound;sound('build');save();syncUI();};$('closeModal').onclick=closeModal;modal.addEventListener('close',()=>{fishingHolding=false;state.outdoors.fishing=null;dismissFeedback();modalView='';});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});document.querySelector('.brand').onclick=e=>{e.preventDefault();closeModal();};
document.addEventListener('visibilitychange',()=>{if(document.hidden){save();active=false;controls?.stop();}else{const result=offlineEarnings(state);lastFrame=performance.now();active=!!scene;if(result.amount>1||result.produced>0)toast('Während deiner Pause: '+format(result.produced)+' Produkte · '+format(result.amount)+' ✧ verkauft.',true);automation=new GardenAutomation(state);syncUI();}});window.addEventListener('pagehide',save);
try{validateContent();scene=new GardenScene($('world'),{reducedMotion:reduced});controls=new GardenControls($('world'),$('joystick'),scene,{blocked:()=>modal.open||hostedFinishPending||state.journey.asleep,onBank:goBank,onTap:(x,y)=>{const id=scene.pickHelper(x,y);if(id)openHelperSnack(id);}});resetWorld();tutorial(state.tutorial);document.body.classList.toggle('reduced-motion',state.reducedMotion);requestAnimationFrame(frame);$('loading').classList.add('done');setTimeout(()=>$('loading').remove(),500);}catch(e){console.error(e);$('loading').hidden=true;$('gameError').hidden=false;}
if(state.journey.asleep)setTimeout(openSleep,700);else if(feedbackPending(state))setTimeout(()=>{if(!modal.open&&feedbackPending(state))openDayFeedback();},700);
if(!state.journey.asleep&&!feedbackPending(state)&&(offline.amount>1||offline.produced>0))setTimeout(()=>{if(state.journey.asleep)return;openModal(title('WILLKOMMEN ZURÜCK','Der Garten war fleißig.',`${format(offline.seconds/60)} Minuten Pause · ${format(offline.produced)} Produkte hergestellt.`)+`<div class="travel-summary">Automatisch verkauft: <b>${format(offline.amount)} ✧</b><br>${'Deine fertigen Produkte warten an den Werkstätten. Während der Pause wird nichts verkauft.'}</div><button class="modal-action" id="backToGarden">Wieder im Garten ankommen</button>`,'offline');$('backToGarden').onclick=closeModal;},700);save();

function syncRoundUI(){const j=state.journey,f=growthFactor(state);$('dayChip').textContent=(j.asleep?'☾ Zz ':j.closed?'☾ ':f<.7?'◔ ':'☀ ')+'Tag '+j.round;$('dayChip').classList.toggle('resting',j.closed||f===0);$('dayGoal').textContent=j.asleep&&j.sleepMissed?'Ohne Tagesbelohnung':j.closed?'Tagesbelohnung ✓':'Tagesbelohnung ↗';$('roundNumber').textContent='Gartentag '+j.round;$('roundMood').textContent=!j.asleep&&j.elapsed>=DAY_RHYTHM.warning?'Du wirst müde · noch '+Math.ceil((DAY_RHYTHM.sleep-j.elapsed)/60)+' Minuten':j.asleep?'Du schläfst · Dieser Gartentag ist vorbei':j.closed?'Ein schöner Gartentag geht zu Ende':f===0?'Die Beete ruhen':f<.2?'Der Garten wird still':f<.7?'Die Beete werden müde':'Ein Garten voller Möglichkeiten';$('roundNote').textContent=j.pending?j.pending+' verdiente Runde'+(j.pending===1?'':'n')+' wartet':j.preview?'Eigenständige Vorschau · Begleit-App noch nicht verbunden':'Ein neuer Eintrag schenkt die nächste Runde';$('roundProgress').style.width=Math.min(100,j.elapsed/DAY_RHYTHM.sleep*100)+'%';$('nextRound').hidden=embedded||!j.pending||!j.closed;$('roundWidget').classList.toggle('resting',f===0);}
function enterNextRound(){if(!startRound(state))return;prepareDay(state,TOOLS);for(const name of discoverSeeds(state))toast('Ein Samen wurde beim Beet gefunden: '+name+'!',true);refreshWorld(false);save();closeModal();toast('Gartentag '+state.journey.round+(state.journey.round<=77?' · Neues Wachstum und +5,5 % Erntewert.':' · Dein Garten erwacht wieder.'),true);sound('build');scene.celebrate(player);}
function openRounds(){const j=state.journey;openModal(title('EIN KLEINER GARTENMOMENT','Deine Gartenrunden.', 'Gartentag '+j.round+' · '+j.pending+' weitere Runden gesammelt.')+'<p>Du wählst deine Ausbauten frei. Neue Runden öffnen nach und nach weitere Stufen und Möglichkeiten. Der reguläre Tagesplan ist auf etwa vier bis fünf Minuten ausgelegt. Zusätzlich früh verfügbare Ausbauten sind freiwillige Möglichkeiten und machen den Tagesabschluss nicht teurer. Du darfst weiter sammeln: Je länger du spielst, desto langsamer wachsen Pflanzen nach. Vorhandene Zutaten, Produkte und Geld bleiben erhalten.</p><p>Ein neuer, auf der Begleitseite gespeicherter Eintrag schenkt sofort eine Runde – auch ohne Internet. Danach gilt eine Pause von zehn Minuten für Eintragsbelohnungen. Gießen lässt dort deine Pflanzen wachsen.</p><button class="modal-action" id="useRound" '+(embedded||!j.pending||!j.closed?'disabled':'')+'>Gesammelte Runde beginnen</button>'+(j.preview?'<div class="preview-note"><strong>Eigenständige Spielvorschau</strong><p>Die Begleit-App ist noch nicht verbunden. Dieser Testknopf simuliert eine verdiente Runde.</p><button class="modal-action secondary" id="previewRound" '+(j.round+j.pending>=10000?'disabled':'')+'>Vorschau: eine Gartenrunde erhalten</button></div>':'')+'<p class="shop-note">Kaufe die Tagesbelohnung vor dem Einschlafen: Nach 10 aktiven Minuten endet jeder Gartentag. Bei einer verpassten Belohnung verlierst du keine Vorräte; fehlende Samen und Gießaktionen bleiben an späteren verdienten Tagen erhältlich. Schneckis Haus braucht drei Bauabschnitte und selbst hergestellte Produkte.</p>','rounds');$('useRound').onclick=enterNextRound;if($('previewRound'))$('previewRound').onclick=()=>{if(grantRound(state,'preview:'+String(j.round+j.pending+1))){save();openRounds();}};}
$('roundWidget').onclick=e=>{if(!e.target.closest('#nextRound')&&!e.target.closest('#dayGoal'))openRounds();};$('nextRound').onclick=enterNextRound;

function openCompanionSeeds(){
 const available=seedCatchupAvailable(state),price=seedCatchupPrice(state),count=rewardCount(state,'seed');
 let html=title('PFLANZEN FÜR DIE BEGLEITSEITE','Deine sieben Samen.','Samen werden an Gartentag 1, 5, 12, 20, 30, 40 und 50 verfügbar: vier bis Tag 20, alle sieben bis Tag 50. Das betrifft deine Begleitpflanzen; die Gartenbeete haben eigene Freischaltungen.')+`<div class="reward-grid"><div>Bereits erhalten<strong>${count} / 7</strong></div><div>Jetzt zusätzlich nachkaufbar<strong>${available}</strong></div></div>`;
 if(available)html+=`<p>Ein früherer Samen fehlt noch? Du kannst ihn zusätzlich kaufen. Deine heutige Tagesbelohnung, bereits erhaltene Gießaktionen und Pflanzen bleiben erhalten. Ein Nachkauf kostet 35 % deiner aktuellen Tagesbelohnung.</p><button class="modal-action" id="buyCatchupSeed" ${state.coins<price?'disabled':''}>Samen nachkaufen · ${format(price)} ✧</button>${state.coins<price?'<p>Dir fehlen noch '+format(price-state.coins)+' ✧.</p>':''}`;
 else html+='<p>'+(!state.journey.closed&&state.journey.rewardKind==='seed'?'Dein aktueller Samen ist als Tagesbelohnung vorgesehen.':'Alle bisher fälligen Samen sind bereits berücksichtigt.')+' Es gibt insgesamt höchstens sieben Samen.</p>';
 html+='<button class="modal-action secondary" id="seedsBack">Zurück zum Gartenmenü</button>';openModal(html,'companion-seeds');
 if($('buyCatchupSeed'))$('buyCatchupSeed').onclick=()=>{if(buyCatchupSeed(state)){save();syncUI();toast('Ein Samen wartet auf der Begleitseite! ❀',true);}openCompanionSeeds();};
 $('seedsBack').onclick=openGardenMenu;
}

function openDayGoal(){if(state.journey.asleep){openSleep();return;}if(state.journey.closed){openDayEnd();return;}const p=getBuildPads(state,TOOLS).find(p=>p.id==='endDay'),kind=state.journey.rewardKind;if(kind==='rest'){openModal(title('EIN RUHIGER FEIERABEND','Gartenpause.','Deine Pflanzenbelohnungen sind vollständig gesammelt. Du kannst den Garten in weiteren verdienten Runden fertig ausbauen.')+'<p>Dieser Tagesabschluss vergibt keine zusätzliche Gießaktion und keinen weiteren Samen.</p>'+padButton(p,'Zum Tagesabschluss ↗'),'day-goal');return;}openModal(title('DEIN KLEINER FEIERABEND','Was wächst in der Begleit-App weiter?','Sichere eine Gießaktion oder einen Samen. Der Kauf beendet diesen Gartentag.')+'<div class="reward-choice"><button id="chooseWater" class="'+(kind==='water'?'selected':'')+'" '+(rewardCount(state,'water')>=70?'disabled':'')+'>☂ Gießkanne</button><button id="chooseSeed" class="'+(kind==='seed'?'selected':'')+'" '+(rewardCount(state,'seed')>=seedsDue(state.journey.round)?'disabled':'')+'>✧ Samen</button></div><p>Bis zum Abschluss kannst du dein Geld frei für Ausbauten verwenden oder auf größere Wünsche sparen.</p><div class="reward-grid"><div>Gießaktionen<strong>'+rewardCount(state,'water')+'</strong></div><div>Samen<strong>'+rewardCount(state,'seed')+'</strong></div></div><p class="shop-note">'+(embedded?'Danach kannst du im Garten bleiben oder zur Begleitseite zurückgehen und deine Pflanzen versorgen.':'Vorschau: Belohnungen werden hier gespeichert.')+'</p>'+padButton(p,'Zum Tagesabschluss ↗'),'day-goal');$('chooseWater').onclick=()=>{state.journey.rewardKind='water';refreshWorld(false);save();openDayGoal();};$('chooseSeed').onclick=()=>{if(rewardCount(state,'seed')>=seedsDue(state.journey.round))return;state.journey.rewardKind='seed';refreshWorld(false);save();openDayGoal();};}
const FEEDBACK_QUESTIONS={
 length:{question:'Wie lange hat es sich angefühlt, die heutige Tagesbelohnung zu erreichen?',left:'Viel zu kurz',right:'Viel zu lang'},
 income:{question:'Wie hat sich das Geldverdienen heute angefühlt?',left:'Viel zu mühsam',right:'Viel zu leicht'},
 workshop:{question:'Wie haben sich die Wartezeiten an den Werkstätten angefühlt?',left:'Viel zu kurz',right:'Viel zu lang'}
};
function openDayFeedback(){
 if(!feedbackPending(state)){openDayEnd();return;}
 const questions=['length','income',...(workshopQuestionAvailable(state)?['workshop']:[])];
 let html='<div class="feedback-page">'+title('DEINE BELOHNUNG IST GESICHERT','Wie war dein Gartentag?','Wenn du magst: Sag kurz, wie es sich für dich angefühlt hat. Dein Garten passt sich für kommende Tage behutsam an. Du kannst die Fragen jederzeit überspringen.')+'<form id="dayFeedbackForm"><button class="feedback-skip-link" type="button" id="skipDayFeedback">Heute überspringen</button>';
 for(const id of questions){const q=FEEDBACK_QUESTIONS[id];html+=`<section class="feedback-question"><label for="feedback-${id}">${q.question}</label><output id="feedback-${id}-value" for="feedback-${id}" aria-live="polite">Genau richtig</output><input type="range" id="feedback-${id}" name="${id}" min="-100" max="100" step="5" value="0" aria-valuetext="Genau richtig" list="feedbackTicks"><div class="feedback-scale" aria-hidden="true"><span>${q.left}</span><span>Genau richtig</span><span>${q.right}</span></div></section>`;}
 html+='<datalist id="feedbackTicks"><option value="-100"></option><option value="0"></option><option value="100"></option></datalist><button class="modal-action" type="submit" id="submitDayFeedback">Rückmeldung speichern</button><button class="modal-action secondary" type="button" id="skipDayFeedbackBottom">Heute überspringen</button></form></div>';
 openModal(html,'feedback');
 for(const id of questions){const slider=$('feedback-'+id),q=FEEDBACK_QUESTIONS[id];slider.oninput=()=>{const value=Number(slider.value),edge=value<0?q.left:q.right,label=Math.abs(value)<10?'Genau richtig':Math.abs(value)>=75?edge:(value<0?q.left.replace('Viel zu','Etwas zu'):q.right.replace('Viel zu','Etwas zu'));$('feedback-'+id+'-value').textContent=label;slider.setAttribute('aria-valuetext',label);};}
 $('dayFeedbackForm').onsubmit=e=>{e.preventDefault();const answers=Object.fromEntries(questions.map(id=>[id,Number($('feedback-'+id).value)]));if(submitFeedback(state,answers)){save();openDayEnd();toast('Danke! Dein Spielgefühl ist für die nächsten Gartentage gespeichert.');}};
 for(const id of ['skipDayFeedback','skipDayFeedbackBottom'])$(id).onclick=()=>{skipFeedback(state);save();openDayEnd();};
}
function openDayEnd(justFinished=false){if(feedbackPending(state)){openDayFeedback();return;}if(state.journey.asleep){openSleep();return;}const j=state.journey;openModal(title('GUT GEMACHT FÜR HEUTE','Ein kleines Stück weiter.',j.rewardKind==='rest'?'Dein Garten kann jetzt ausruhen.':(j.rewardKind==='seed'?'Ein Samen':'Eine Gießaktion')+' wurde als Belohnung vorgemerkt.')+'<p>Du kannst noch durch den Garten laufen, ernten, Zutaten abliefern und Stapel verkaufen. Nach insgesamt 10 aktiven Minuten schläfst du ein. Ab Minute neun wachsen Pflanzen nicht mehr nach; reife Pflanzen kannst du noch ernten. Freigeschaltete Upgrades und freiwillige Wünsche bleiben bis zum Einschlafen kaufbar.</p><div class="reward-grid"><div>Gießaktionen<strong>'+rewardCount(state,'water')+'</strong></div><div>Samen<strong>'+rewardCount(state,'seed')+'</strong></div></div><p class="shop-note">'+(embedded?'Deine Belohnung kannst du direkt auf der Begleitseite einpflanzen oder auf eine Pflanze gießen.':'Die Belohnung bleibt in dieser eigenständigen Vorschau gespeichert.')+'</p><button class="modal-action" id="nightGarden">Noch ein bisschen im Garten bleiben</button><button class="modal-action secondary" id="daySeeds">Begleitpflanzen & Samen nachkaufen</button><button class="modal-action secondary" id="dayRounds">Gartenrunden ansehen</button>'+(embedded?'<button class="modal-action" id="returnPlants">Zurück zu meinen Pflanzen</button>':''),'day-end');$('nightGarden').onclick=closeModal;$('dayRounds').onclick=openRounds;$('daySeeds').onclick=openCompanionSeeds;if($('returnPlants'))$('returnPlants').onclick=finishHostedDay;}
$('dayGoal').onclick=e=>{e.stopPropagation();openDayGoal();};



function openGardenMenu(){openModal(title('DEIN KLEINER RÜCKZUGSORT','Mondgarten.','Gartentag '+state.journey.round)+`<div class="menu-route"><button class="modal-action secondary" id="menuSell">Verkaufen ↗</button><button class="modal-action secondary" id="menuStore">Ins Lager ↗</button></div><div class="garden-menu"><button id="menuGoal"><span>☾</span><div><strong>Tagesbelohnung</strong><small>Gießaktion oder Samen sichern</small></div></button><button id="menuSeeds"><span>✧</span><div><strong>Begleitpflanzen & Samen</strong><small>Frühere Samen zusätzlich nachkaufen</small></div></button><button id="menuBuild"><span>❀</span><div><strong>Garten ausbauen</strong><small>Beete, Werkzeuge & kleine Helfer</small></div></button>${state.village.farm.built?'<button id="menuFarm"><span>꩜</span><div><strong>Schneckenfarm</strong><small>Aufzucht & Futter herstellen</small></div></button>':''}<button id="menuSnails"><span>꩜</span><div><strong>Deine Schnecken</strong><small>Namen, Aufgaben & Nachtruhe</small></div></button><button id="menuApiary"><span>⬡</span><div><strong>Bienen & Honig</strong><small>Körbe, Honig und Honigäpfel</small></div></button><button id="menuStock"><span>▤</span><div><strong>Vorräte & Produktion</strong><small>Zutaten und fertige Produkte</small></div></button><button id="menuBoutiques"><span>✿</span><div><strong>Dekoration & Kleidung</strong><small>Dauerhafte Läden und kleine Wünsche</small></div></button><button id="menuOutdoors"><span>♧</span><div><strong>Werkzeuge & Entdeckungen</strong><small>Metalldetektor, Angeln & Dünger</small></div></button><button id="menuSettings"><span>⚙</span><div><strong>Einstellungen</strong><small>Klang, Namen & Spielstand</small></div></button></div>`,'garden-menu');$('menuSell').onclick=goBank;$('menuStore').onclick=goWarehouse;$('menuGoal').onclick=openDayGoal;$('menuBuild').onclick=openBuildMenu;$('menuSeeds').onclick=openCompanionSeeds;$('menuApiary').onclick=openApiary;$('menuStock').onclick=openInventory;$('menuSnails').onclick=openSnails;if($('menuFarm'))$('menuFarm').onclick=openFarm;$('menuOutdoors').onclick=openOutdoors;$('menuSettings').onclick=openSettings;$('menuBoutiques').onclick=openBoutiques;}
$('gardenMenu').onclick=openGardenMenu;$('dayChip').onclick=openDayGoal;

if(embedded){window.addEventListener('storage',e=>{if(e.key!==COMPANION.journalKey)return;try{if(syncCompanionActions(state,JSON.parse(e.newValue||'null'))){prepareDay(state,TOOLS);refreshWorld(false);save();toast('Ein verdienter Gartentag wartet auf dich.');}}catch{}});window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.type==='mondgarten:save'){controls?.stop();save();}if(e.origin===location.origin&&e.source===parent&&e.data?.type==='mondgarten:start'){if(state.journey.closed&&state.journey.pending)enterNextRound();}});}

let hostedFinishPending=false;
function finishHostedDay(){
 if(hostedFinishPending)return;const missed=state.journey.asleep&&state.journey.sleepMissed;hostedFinishPending=true;controls?.stop();closeModal();save();
 const cover=document.createElement('div');cover.className='hosted-day-finish';cover.setAttribute('role','status');
 const symbol=document.createElement('span'),text=document.createElement('strong'),note=document.createElement('p');symbol.textContent=state.journey.rewardKind==='water'?'☂':'❀';text.textContent=missed?'Der Garten ruht.':'Ein schöner Gartentag geht zu Ende.';note.textContent=missed?'Beim nächsten verdienten Gartentag geht es weiter.':state.journey.rewardKind==='water'?'Deine Gießkanne wartet bei deinen Pflanzen.':state.journey.rewardKind==='seed'?'Ein neuer Samen wartet auf sein Plätzchen.':'Zurück zu deinen Pflanzen.';cover.append(symbol,text,note);document.body.append(cover);
 setTimeout(()=>{save();parent.postMessage({type:'mondgarten:day-ended',round:state.journey.round,kind:missed?'rest':state.journey.rewardKind},location.origin);},state.reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?350:1900);
}

function openBoutiques(){
 const b=state.village.boutiques;
 let html=title('KLEINE WÜNSCHE BLEIBEN','Eure Gartenläden.','Teurere Läden baut ihr einmal. Danach könnt ihr immer wieder etwas für Deko oder Accessoires einzahlen. Im fertigen Laden sind alle Artikel sofort verfügbar. Große Wünsche kosten mehr. Jede Anzahlung bleibt über Tage und Pausen erhalten. Dekoration und Kleidung sind freiwillig. Im Accessoiresladen gibt es außerdem Werkzeuge für neue Gartenaktivitäten.');
 const funding=(d,construction=false)=>{const paid=b.payments[d.id]??0,cost=cosmeticPrice(d.id),locked=!cosmeticAvailable(state,d.id);return `<article class="upgrade-card"><h3>${esc(d.name)}${construction?' · Laden bauen':''}</h3><p>${esc(d.description)}</p><p>${locked?'Ab Gartentag '+d.round:format(paid)+' / '+format(cost)+' ✧ angespart'}</p>${locked?'':`<progress max="${cost}" value="${paid}" aria-label="${esc(d.name)} angespart"></progress><div class="settings-row">${[100,1000].map(n=>`<button class="modal-action secondary" data-cosmetic="${d.id}" data-amount="${n}" ${state.coins<=0?'disabled':''}>Bis zu ${format(n)} ✧</button>`).join('')}</div><button class="modal-action secondary" data-cosmetic="${d.id}" data-amount="${cost-paid}" ${state.coins<=0?'disabled':''}>Rest einzahlen · ${format(cost-paid)} ✧</button>`}</article>`;};
 for(const shop of BOUTIQUES){if(!b.built.includes(shop.id)){html+=funding(shop,true);continue;}html+='<h3>'+esc(shop.name)+' · Gebaut ✓</h3>';for(const d of COSMETICS.filter(d=>d.shop===shop.id)){if(!b.owned.includes(d.id)){html+=funding(d);continue;}html+=`<article class="upgrade-card"><h3>${esc(d.name)} ✓</h3><p>${esc(d.description)}</p>${d.shop==='decor'?'<p>Steht in eurem Garten.</p>':[0,1].map(i=>`<button class="modal-action secondary" data-equip="${d.id}" data-actor="${i}">${esc(state.names[i])}: ${b.equipped[i]===d.id?'Ablegen':'Anziehen'}</button>`).join('')}${SNAIL_HATS.includes(d.id)?`<button class="modal-action secondary" data-snail-hats="${d.id}">Schnecken ausstatten</button>`:''}</article>`;}}
 if(b.built.includes('style'))html+='<h3>Werkzeuge · Faden & Blüte</h3>'+OUTDOOR_TOOLS.map(t=>`<article class="upgrade-card"><h3>${t.name}</h3><p>${t.description}</p><button class="modal-action secondary" data-outdoor-buy="${t.id}" ${state.outdoors.owned.includes(t.id)||state.coins<t.cost?'disabled':''}>${state.outdoors.owned.includes(t.id)?'Gekauft ✓':format(t.cost)+' ✧ · Kaufen'}</button></article>`).join('');html+='<button class="modal-action" id="openOutdoorTools">Werkzeuge & Gartenaktivitäten</button>';
 openModal(html,'boutiques');$('openOutdoorTools').onclick=openOutdoors;modal.querySelectorAll('[data-outdoor-buy]').forEach(el=>el.onclick=()=>{if(buyOutdoorTool(state,el.dataset.outdoorBuy)){refreshWorld(false);save();openBoutiques();}});
 modal.querySelectorAll('[data-cosmetic]').forEach(el=>el.onclick=()=>{const result=contributeCosmetic(state,el.dataset.cosmetic,Number(el.dataset.amount));if(result.paid){refreshWorld(false);save();if(result.complete){sound('build');toast('Ein Wunsch ist fertig: '+[...BOUTIQUES,...COSMETICS].find(d=>d.id===el.dataset.cosmetic).name,true);}openBoutiques();}});
 modal.querySelectorAll('[data-snail-hats]').forEach(el=>el.onclick=()=>openSnailHats(el.dataset.snailHats));
 modal.querySelectorAll('[data-equip]').forEach(el=>el.onclick=()=>{const actor=Number(el.dataset.actor),id=el.dataset.equip;equipCosmetic(state,actor,b.equipped[actor]===id?null:id);save();openBoutiques();});
}

function openSnails(){
 automation.sync(state);
 let html=title('KLEINE HELFER, EIGENE AUFGABEN','Deine Schnecken.','Pro freigeschaltetem Feld ist eine gekaufte Schnecke möglich; weitere Helfer bis insgesamt zwölf ziehst du in der Farm auf. Gib jeder Schnecke einen Namen und eine Aufgabe. Bei Dunkelheit ziehen sich alle ins Häuschen zurück. Getragene Waren bleiben sicher bis zum Morgen.');
 if(!state.village.snails)html+='<p>Noch keine Helferschnecke eingezogen. Du kannst später Schnecken kaufen oder in der Farm aufziehen.</p>';
 for(let i=0;i<state.village.snails;i++){
  const profile=snailProfile(state,i),snail=automation.snails[i],species=SNAILS.find(n=>n.id===snail.species);
  html+=`<article class="upgrade-card snail-care-card"><h3 data-snail-heading="${i}">${esc(snailName(state,i))}</h3><p>${esc(species?.name??'Ernteschnecke')} · ${snail.sleeping?'Im Häuschen eingekuschelt':snail.mode==='deliver'?'Mit Ernte unterwegs':'Bereit zum Helfen'}${snail.bag?' · '+format(snail.bag)+' getragen':''}</p><label class="field">Name<input data-snail-name="${i}" maxlength="24" value="${esc(profile.name)}" placeholder="Schnecke ${i+1}" autocomplete="off"></label><label class="field">Aufgabe<select data-snail-task="${i}">${Object.entries(SNAIL_TASKS).map(([id,label])=>`<option value="${id}" ${profile.task===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Erntebereich<select data-snail-field="${i}"><option value="" ${profile.field===null?'selected':''}>Alle Felder · automatisch verteilen</option>${BEDS.map((bed,index)=>state.village.beds[index]?`<option value="${index}" ${profile.field===index?'selected':''}>${esc(bed.name)}</option>`:'').join('')}</select></label><button class="modal-action secondary" data-helper-snack="snail:${i}">Honighäppchen geben</button></article>`;
 }
 html+='<p class="shop-note">Werkstatt: passende Zutaten abliefern, Überschuss verkaufen. Lager: Ernte einlagern; bei vollem Lager mit der Ladung warten. Ausruhen: sofort Pause machen. Erntebereich: Wähle ein freigeschaltetes Beet oder den Obstgarten. Fest zugewiesene Schnecken warten dort auf neue Ernte. Vorhandene Ladung wird zuerst ausgeliefert. Namen, Aufgaben und Bereiche werden gespeichert.</p><button class="modal-action secondary" id="snailButterflies">Schmetterlingssammlung & Flügel</button><button class="modal-action secondary" id="snailsBack">Zurück zum Gartenmenü</button>';
 openModal(html,'snails');
 modal.querySelectorAll('[data-snail-name]').forEach(input=>input.oninput=()=>{const i=Number(input.dataset.snailName);setSnailProfile(state,i,{...snailProfile(state,i),name:input.value});modal.querySelector(`[data-snail-heading="${i}"]`).textContent=snailName(state,i);automation.sync(state);save();});
 modal.querySelectorAll('[data-snail-task]').forEach(input=>input.onchange=()=>{const i=Number(input.dataset.snailTask);setSnailProfile(state,i,{...snailProfile(state,i),task:input.value});automation.sync(state);save();openSnails();});
 modal.querySelectorAll('[data-snail-field]').forEach(input=>input.onchange=()=>{const i=Number(input.dataset.snailField);setSnailProfile(state,i,{...snailProfile(state,i),field:input.value===''?null:Number(input.value)});automation.sync(state);save();openSnails();});
 modal.querySelectorAll('[data-helper-snack]').forEach(b=>b.onclick=()=>openHelperSnack(b.dataset.helperSnack));$('snailButterflies').onclick=openJournal;$('snailsBack').onclick=openGardenMenu;
}

function openSnailHats(id){
 const b=state.village.boutiques,d=COSMETICS.find(d=>d.id===id);if(!d||!SNAIL_HATS.includes(id)||!b.owned.includes(id))return;
 let html=title('HÜTE FÜR KLEINE HELFER',d.name,'Einmal gekauft, kann der Hut gleichzeitig von Figuren und Schnecken getragen werden. Hüte verändern die Arbeitsleistung nicht.');
 if(!state.village.snails)html+='<p>Du hast noch keine Helferschnecke. Sobald eine eingezogen ist, kannst du sie hier ausstatten.</p>';
 else{
  html+='<button class="modal-action secondary" id="hatAllSnails">Allen diesen Hut aufsetzen</button>';
  for(let i=0;i<state.village.snails;i++){
   const species=SNAILS.find(n=>n.id===state.village.farm.helpers[i]),hat=COSMETICS.find(d=>d.id===b.snailHats[i]);
   html+=`<article class="upgrade-card"><h3>${esc(snailName(state,i))}</h3><p>${hat?esc(hat.name):'Kein gekaufter Hut aufgesetzt.'}</p><button class="modal-action secondary" data-hat-snail="${i}">${b.snailHats[i]===id?'Hut abnehmen':'Hut aufsetzen'}</button></article>`;
  }
 }
 html+='<button class="modal-action secondary" id="snailHatsBack">Zurück zum Laden</button>';openModal(html,'snail-hats');
 const finish=()=>{automation.sync(state);save();openSnailHats(id);};
 modal.querySelectorAll('[data-hat-snail]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.hatSnail);if(equipSnailHat(state,i,b.snailHats[i]===id?null:id))finish();});
 if($('hatAllSnails'))$('hatAllSnails').onclick=()=>{for(let i=0;i<state.village.snails;i++)equipSnailHat(state,i,id);finish();};
 $('snailHatsBack').onclick=openBoutiques;
}

function openSleep(){
 const j=state.journey;if(!j.asleep)return;
 const note=j.rewardKind==='rest'&&!j.sleepMissed?'Dieser Gartentag ist abgeschlossen. Alle Pflanzenbelohnungen sind bereits gesammelt.':j.sleepMissed?'Heute bist du vor dem Kauf eingeschlafen. Für diesen Gartentag gibt es keine neue Pflanzenbelohnung. Fehlende Belohnungen kannst du an späteren verdienten Tagen kaufen.':'Deine gekaufte Pflanzenbelohnung bleibt erhalten.';
 openModal(title('GUTE NACHT, KLEINER GARTEN','Einfach eingekuschelt.',note)+'<p>Geld, Waren, Baufortschritt und Anzahlungen sind sicher. Eine angefangene Zahlung für die Tagesbelohnung wurde zurückgegeben. Eine neue verdiente Runde weckt dich wieder.</p>'+(embedded?'<button class="modal-action" id="sleepReturn">Zur Begleitseite</button>':'')+'<button class="modal-action secondary" id="sleepSeeds">Begleitpflanzen & Samen nachkaufen</button><button class="modal-action secondary" id="sleepRounds">Gartenrunden ansehen</button><button class="modal-action secondary" id="sleepSettings">Einstellungen & Sicherung</button>','sleep');
 if($('sleepReturn'))$('sleepReturn').onclick=finishHostedDay;$('sleepRounds').onclick=openRounds;$('sleepSeeds').onclick=openCompanionSeeds;$('sleepSettings').onclick=openSettings;
}

let boutiqueVisit=null,boutiqueDwell=0;
function updateBoutiqueEntry(dt){
 const shop=BOUTIQUES.find(d=>state.journey.round>=d.round&&Math.hypot(player.x-d.x,player.z-(d.z+1.8))<1.25);
 if(!shop){boutiqueVisit=null;boutiqueDwell=0;return;}
 if(!dt||player.moving||boutiqueVisit===shop.id){boutiqueDwell=0;return;}
 boutiqueDwell+=dt;if(boutiqueDwell>=.8){boutiqueVisit=shop.id;boutiqueDwell=0;openBoutiques();}
}

function updateOutdoorPlay(dt,growthDelta,time){
 for(const event of advanceOutdoors(state,cells,player,dt,growthDelta,time,i=>bedYield(state,i))){
  if(event.kind==='compost')toast('Drei Portionen Dünger warten an deiner Düngerwerkstatt.',true);
  else if(event.kind==='buriedShell')toast('Ausgegraben: '+event.name+'! In der Schneckenfarm findest du dein Häuschen.',true);
  else toast('Ein kleiner Schatz! Am Verkaufsstand verkaufen.',true);
  save();
 }
 if(dt>0){const n=collectFertilizer(state,player);if(n){scene.makeFertilizerPickup(COMPOST_WORKSHOP.output,n);floater(player.x,player.z,'+ '+n+' Dünger',true);syncUI();save();}detectorBeep+=dt;const target=detectorTarget(state,player);if(target&&detectorBeep>.25+Math.hypot(target.x-player.x,target.z-player.z)*.15){sound('detector');detectorBeep=0;}
  if(inBank(player.x,player.z)){const sold=sellOutdoorGoods(state);if(sold.count){floater(player.x,player.z,'Fundstücke & Fische: + '+precise(sold.value)+' ✧',true);scene.receiveMoney(player,sold.value);save();}}
  if(modal.open&&modalView==='fishing'){const event=advanceFishing(state,dt,fishingHolding);if(event){fishingHolding=false;save();if(event.kind==='fish'){toast(event.fish.name+' gefangen!',true);openOutdoors();}else{toast('Der Fisch ist entwischt. Du kannst es erneut versuchen.');openOutdoors();}}else updateFishingUI();}
 }
}
function updateOutdoorHUD(){
 const o=state.outdoors,hud=$('outdoorHUD');if(!hud)return;
 const nearWorkshop=o.composterBuilt&&Math.hypot(player.x-COMPOST_WORKSHOP.x,player.z-COMPOST_WORKSHOP.z)<4;
 hud.hidden=(!o.owned.length&&!nearWorkshop)||state.journey.asleep;
 const t=OUTDOOR_TOOLS.find(t=>t.id===o.equipped);$('outdoorOpen').textContent=t?t.name:'Werkzeuge';
 const action=$('outdoorAction');action.hidden=o.equipped!=='rod';action.disabled=Math.hypot(player.x-LAKE.shore.x,player.z-LAKE.shore.z)>3;action.textContent='Angel auswerfen';
 $('outdoorWorkshop').hidden=!nearWorkshop;
 const target=detectorTarget(state,player);$('outdoorSignal').textContent=target?(o.dig?'Grabe aus … '+Math.floor(o.dig/2*100)+' %':'Signal · '+Math.hypot(target.x-player.x,target.z-player.z).toFixed(1)+' m · am Ring stehen bleiben'):o.equipped==='detector'?'Nach Signalen in Feldern und um die Farm suchen.':o.equipped==='rod'?'Zum See im Südwesten gehen.':'';
 const hasFertilizer=o.fertilizer>0&&!state.journey.asleep,mode=o.harvestMode==='fertilizer';
 $('harvestModes').hidden=!hasFertilizer;document.getElementById('game').classList.toggle('has-fertilizer',hasFertilizer);
 $('modeScythe').setAttribute('aria-pressed',String(!mode));$('modeFertilizer').setAttribute('aria-pressed',String(mode));$('modeFertilizer').textContent='Düngen · '+o.fertilizer;$('sprayFertilizer').hidden=!mode;
}
function openOutdoors(){
 const o=state.outdoors;let html=title('KLEINE SCHÄTZE IM GARTEN','Werkzeuge & Entdeckungen.','Werkzeuge kaufst du einmal im Accessoiresladen. Wähle hier, was du mitnehmen möchtest.');
 html+=OUTDOOR_TOOLS.map(t=>`<article class="upgrade-card"><h3>${t.name}</h3><p>${t.description}</p>${o.owned.includes(t.id)?`<button class="modal-action secondary" data-outdoor-equip="${t.id}">${o.equipped===t.id?'Werkzeug ablegen':'Ausrüsten'}</button>`:'<p>Im gebauten Accessoiresladen erhältlich: '+format(t.cost)+' ✧.</p>'}</article>`).join('');
 html+='<h3>Fundbeutel</h3><p>'+(o.treasures||0)+' Kleinfunde · '+o.dug.length+' / 2 vergrabene Schneckenhäuser gefunden.</p>'+FISH.map(f=>'<p>'+f.name+': '+(o.fish[f.id]??0)+'</p>').join('')+'<button class="modal-action secondary" id="outdoorSell">Fische & Kleinfunde zum Verkaufsstand bringen ↗</button>';
 if(o.owned.includes('rod'))html+='<button class="modal-action secondary" id="outdoorLake">Zum See ↗</button><button class="modal-action" id="outdoorFish" '+(o.equipped!=='rod'||Math.hypot(player.x-LAKE.shore.x,player.z-LAKE.shore.z)>3?'disabled':'')+'>Angel auswerfen</button><p>Am See den Knopf halten oder loslassen, damit der Marker im grünen Bereich bleibt. Fische sind im Fundbeutel; du kannst sie verkaufen oder im Komposter verarbeiten.</p>';
 html+='<h3>Düngerwerkstatt</h3><p>Dünger entsteht in einer eigenen kleinen Werkstatt. Fertige Portionen dort abholen; mit Dünger im Beutel kannst du unten zwischen Sense und Düngen wechseln.</p>'+(o.composterBuilt?'<button class="modal-action secondary" data-composter>Werkstatt öffnen</button>':padButton(getBuildPads(state,TOOLS).find(p=>p.id==='composter'),'Düngerwerkstatt bauen ↗'));
 html+='<button class="modal-action secondary" id="outdoorShop">Zum Accessoiresladen</button>';openModal(html,'outdoors');
 modal.querySelectorAll('[data-outdoor-equip]').forEach(el=>el.onclick=()=>{equipOutdoorTool(state,o.equipped===el.dataset.outdoorEquip?null:el.dataset.outdoorEquip);refreshWorld(false);save();openOutdoors();});
 $('outdoorShop').onclick=openBoutiques;$('outdoorSell').onclick=goBank;if($('outdoorLake'))$('outdoorLake').onclick=()=>walkTo(LAKE.shore);if($('outdoorFish'))$('outdoorFish').onclick=openFishing;

}
function openCompostWorkshop(){
 const o=state.outdoors;if(!o.composterBuilt){goPad('composter');return;}
 openModal(title('EINE KLEINE WERKSTATT IM GRÜNEN','Düngerwerkstatt.','Aus gelagerten Blumen oder gefangenen Fischen wird Dünger.')+'<p id="compostStatus" role="status"></p><progress id="compostProgress" max="60" value="0" aria-label="Düngerproduktion"></progress><button class="modal-action secondary" id="compostFlowers">12 gelagerte Blumen → 3 Dünger</button><button class="modal-action secondary" id="compostFish">2 Fische → 3 Dünger</button><button class="modal-action" id="compostCollect">Fertigen Dünger abholen ↗</button><p>60 aktive Sekunden pro Charge. Die Produktion pausiert im Menü. Fertiger Dünger schwebt rechts neben der Werkstatt und wird beim Näherkommen eingesammelt.</p><p>Unten zwischen Sense und Düngen wechseln. Im Düngemodus bleibt die Ernte aus. Eine Sprühportion wirkt drei Minuten auf die getroffene Stelle eines Blumenfelds: doppelte Höhe, doppelte Nachwachsrate und +20 % Erntewert.</p>','composter');
 for(const [id,recipe]of [['compostFlowers','flowers'],['compostFish','fish']])$(id).onclick=()=>{if(startCompost(state,recipe)){save();updateCompostUI();}else toast('Es fehlen Zutaten oder Platz für fertigen Dünger.');};
 $('compostCollect').onclick=()=>walkTo(COMPOST_WORKSHOP.output);updateCompostUI();
}
function updateCompostUI(){const o=state.outdoors,c=o.compost;if(!$('compostStatus'))return;$('compostStatus').textContent=c.remaining?'Produziert · noch '+Math.ceil(c.remaining)+' aktive Sekunden.':c.ready?c.ready+' Portionen warten auf Abholung.':'Bereit für eine neue Charge.';$('compostStatus').textContent+=' · '+o.fertilizer+' Dünger dabei.';$('compostProgress').value=c.remaining?60-c.remaining:c.ready?60:0;
 for(const id of ['compostFlowers','compostFish'])$(id).disabled=!!c.remaining||c.ready>21;$('compostCollect').disabled=!c.ready;
}
function openFishing(){
 if(!startFishing(state,player,bedYield(state,0))){toast('Rüste die Angel aus und stelle dich ans Ufer.');return;}
 fishingHolding=false;openModal(title('EIN RUHIGER MOMENT AM SEE','Petri Heil.')+'<p id="fishingStatus" role="status">Die Angel ist ausgeworfen …</p><div class="fishing-track" aria-hidden="true"><span id="fishingTarget"></span><b id="fishingMarker"></b></div><progress id="fishingProgress" max="1" value="0" aria-label="Fangfortschritt"></progress><button class="modal-action" id="fishingHold">Halten zum Anheben · loslassen zum Senken</button><p>Warte auf den Biss. Halte den Knopf oder die Leertaste, um den Marker anzuheben. Bleibe im grünen Bereich, bis der Fangbalken voll ist.</p><button class="modal-action secondary" id="fishingCancel">Angeln abbrechen</button>','fishing');
 const hold=$('fishingHold');hold.onpointerdown=e=>{e.preventDefault();hold.setPointerCapture(e.pointerId);fishingHolding=true;};for(const event of ['pointerup','pointercancel','lostpointercapture','blur'])hold.addEventListener(event,()=>fishingHolding=false);
 hold.onkeydown=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();e.stopPropagation();fishingHolding=true;}};hold.onkeyup=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();e.stopPropagation();fishingHolding=false;}};hold.focus();$('fishingCancel').onclick=()=>{state.outdoors.fishing=null;fishingHolding=false;openOutdoors();};
}
function updateFishingUI(){const f=state.outdoors.fishing;if(!f||!$('fishingStatus'))return;$('fishingStatus').textContent=f.phase==='waiting'?'Die Pose treibt … warte auf den Biss.':'Ein Fisch beißt! Halte den Marker im grünen Bereich.';$('fishingTarget').style.left=(f.target-.18)*100+'%';$('fishingMarker').style.left=f.marker*100+'%';$('fishingProgress').value=f.progress;}
$('outdoorOpen').onclick=openOutdoors;$('outdoorAction').onclick=openFishing;$('outdoorWorkshop').onclick=openCompostWorkshop;
for(const [id,mode]of [['modeScythe','scythe'],['modeFertilizer','fertilizer']])$(id).onclick=()=>{if(setHarvestMode(state,mode)){harvestClock=0;for(const c of cells){c.pickProgress=0;c.mineProgress=0;}refreshWorld(false);save();}};
$('sprayFertilizer').onclick=()=>{if(sprayFertilizer(state,cells,player)){save();sound('harvest');scene.harvestFlash(player.x,player.z,'lavender');syncUI();}else toast('Mit Dünger auf ein Blumenfeld stellen.');};
window.addEventListener('blur',()=>fishingHolding=false);
